"""Verifier for styled-decay-curves. Generated by scripts/build_harbor_tasks.py.

S1 cheap artifact checks, S2 content checks on the manifest of a re-run of
plot.py, S3 delivered PNG == fresh render, S5 sidecar against the answer key.
Machinery: verifier_core.py (adapted from harbor/example/tests/test_state.py).

Known blind spots (the point of the second mutant): nothing here measures
legibility -- tick-label rotation, overlap, clipping at the image edge, or
contrast -- and line dash patterns and legend placement are only partly checked.
"""

from pathlib import Path

import pytest

from verifier_core import (
    APP, DELIVERED_FIGURE, assert_close, axes, bar_containers, check_input_unchanged,
    check_rerender_matches, check_valid_nonblank_png, delivered, find_script, lines,
    load_sidecar, norm_colour, snapshot_delivered, reexecute,
)

INPUTS = {}


@pytest.fixture(scope="session")
def manifest():
    snapshot_delivered()
    return reexecute(Path("/tmp/reexec"))


def test_s1_figure_is_a_valid_nonblank_png():
    snapshot_delivered()
    check_valid_nonblank_png()


def test_s1_inputs_unchanged():
    for name, digest in INPUTS.items():
        check_input_unchanged(name, digest)


def test_s1_plotting_script_left_behind():
    assert find_script().stat().st_size > 0


def test_s3_delivered_png_matches_a_fresh_render(manifest):
    check_rerender_matches(manifest)


def png_size():
    from PIL import Image

    with Image.open(delivered(DELIVERED_FIGURE)) as image:
        return image.size

import math

T = [i * 0.05 for i in range(201)]
FUNCS = {
    "f1": [math.exp(-0.5 * t) for t in T],
    "f2": [math.exp(-t) for t in T],
    "f3": [0.5 * math.exp(-2 * t) + 1e-4 for t in T],
}
STYLE = {  # label -> (function, colour, linestyle, marker)
    "exp(-0.5t)": ("f1", "#1b9e77", "-", "o"),
    "exp(-t)": ("f2", "#d95f02", "--", "s"),
    "0.5exp(-2t)+1e-4": ("f3", "#7570b3", "-.", "^"),
}


def test_s5_sidecar_matches_formulas():
    declared = load_sidecar()
    assert sorted(declared) == ["f1", "f2", "f3", "t"], f"sidecar keys {sorted(declared)}"
    assert_close(declared["t"], T, 1e-9, "t")
    for name, values in FUNCS.items():
        assert_close(declared[name], values, 1e-9, name)


def test_s2_three_styled_lines(manifest):
    found = {line.get("label"): line for line in lines(manifest)}
    for label, (name, colour, style, marker) in STYLE.items():
        assert label in found, f"no line labelled {label!r} (lines: {sorted(found)})"
        line = found[label]
        assert_close(line["y"], FUNCS[name], 1e-9, f"{label} y values")
        assert norm_colour(line["colour"]) == colour, f"{label} colour {line['colour']}"
        assert line.get("linestyle") == style, f"{label} linestyle {line.get('linestyle')!r}"
        assert line.get("marker") == marker, f"{label} marker {line.get('marker')!r}"
        assert abs(float(line.get("linewidth", 0)) - 2) < 1e-9, f"{label} linewidth {line.get('linewidth')}"


def test_s2_log_axis_limits_text_grid(manifest):
    ax = axes(manifest)
    assert ax["yscale"] == "log", f"y scale {ax['yscale']}"
    assert abs(ax["ylim"][0] - 1e-5) < 1e-12 and abs(ax["ylim"][1] - 2) < 1e-9, f"ylim {ax['ylim']}"
    assert abs(ax["xlim"][0]) < 1e-9 and abs(ax["xlim"][1] - 10) < 1e-9, f"xlim {ax['xlim']}"
    assert ax["xlabel"] == "t (s)" and ax["ylabel"] == "amplitude"
    assert ax["title"] == "Three decays on a log scale"
    assert ax.get("grid_visible") is True, "grid lines are not shown"
    legend = (ax.get("legend") or {}).get("labels", [])
    assert set(STYLE) <= set(legend), f"legend {legend}"


def test_s2_figure_is_8_by_5_inches_at_150_dpi():
    assert png_size() == (1200, 750), f"figure.png is {png_size()}, expected 1200x750"
